#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Load the script under test\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)\nsource "$SCRIPT_DIR/src/disk_guardian.sh"\n\n# Enable deterministic message selection\nexport DISK_GUARDIAN_TEST=1\n\n# Helper to capture output of main with a mocked get_usage\nfunction run_main_with_usage() {\n  local mocked_usage=$1\n  local threshold=$2\n  # Override get_usage for this subshell\n  (\n    function get_usage() {\n      echo "$mocked_usage"\n    }\n    main "$threshold"\n  )\n}\n\n# Test case: usage below threshold\noutput=$(run_main_with_usage 45 80)\nexpected="✅ Disk usage 45% is within safe limits (80%)."\nif [[ "$output" != "$expected" ]]; then\n  echo "FAIL: Expected safe message, got: $output"\n  exit 1\nfi\n\n# Test case: usage exactly at threshold\noutput=$(run_main_with_usage 80 80)\nexpected_prefix="🚨 Disk usage 80% exceeds threshold 80%."\nif [[ "$output" != $expected_prefix* ]]; then\n  echo "FAIL: Expected warning at threshold, got: $output"\n  exit 1\nfi\n\n# Test case: usage above threshold\noutput=$(run_main_with_usage 92 75)\nexpected_prefix="🚨 Disk usage 92% exceeds threshold 75%."\nif [[ "$output" != $expected_prefix* ]]; then\n  echo "FAIL: Expected warning above threshold, got: $output"\n  exit 1\nfi\n\n# Test case: invalid threshold argument\nif run_main_with_usage 50 abc 2>/dev/null; then\n  echo "FAIL: Expected non‑zero exit for invalid threshold"\n  exit 1\nfi\n\necho "All tests passed."\n
